"""Hex-grid map that wraps on both axes (c++): offset coordinates, neighbours, torus distance, ranges, stepping and flood-fill regions; bugs injected into the library."""
from fx import Lib, dd

from generators.fix import _lang3

README1 = dd(r'''
    # hexwrap

    Helpers for a board game played on a hexagonal map that wraps around on both axes (a torus).

    ## Coordinates

    Cells are addressed in **odd-r offset coordinates**: `Hex{col, row}` with rows running down. Hexes are "pointy-top", and every
    **odd** row is shifted half a cell to the right. A `Map(w, h)` has `w` columns and `h` rows; `h` must be even (so that the shifted
    rows line up when the map wraps vertically). The constructor throws `std::invalid_argument` unless `w >= 1` and `h >= 2` and `h`
    is even.

    Any `col` and `row` (negative or large) are accepted by the methods below and are first reduced into the map with `wrap`: `col` modulo `w` and
    `row` modulo `h`, always into `0 <= col < w`, `0 <= row < h` (`-1` becomes `w - 1` / `h - 1`). Results are always in that canonical form.

    ## Directions

    `enum Dir { E, NE, NW, W, SW, SE }` (values 0..5, in this order). From a cell `(col, row)` the neighbour in each direction is:

    | direction | even row | odd row |
    |---|---|---|
    | E  | `(col+1, row)`   | `(col+1, row)` |
    | W  | `(col-1, row)`   | `(col-1, row)` |
    | NE | `(col, row-1)`   | `(col+1, row-1)` |
    | NW | `(col-1, row-1)` | `(col, row-1)` |
    | SE | `(col, row+1)`   | `(col+1, row+1)` |
    | SW | `(col-1, row+1)` | `(col, row+1)` |

    The parity is that of the (wrapped) row of the cell you start from. The neighbour is then wrapped. On small maps two directions can lead to the same cell.

    ## `class Map`

    * `Hex wrap(Hex h) const`; `int index(Hex h) const` (row-major index `row * w + col` of the wrapped cell); `Hex from_index(int i) const`.
    * `std::array<Hex, 6> neighbors(Hex h) const`: the six neighbours in direction order `E, NE, NW, W, SW, SE` (duplicates stay in place).
    * `Hex step(Hex h, Dir d, int n) const`: move `n` cells in direction `d`, one neighbour step at a time (the row parity is re-evaluated
      after every step); a negative `n` moves in the opposite direction (`d + 3 mod 6`) `-n` times. `n == 0` returns the wrapped `h`.
      `std::invalid_argument` when `|n| > 10000`.
    * `int distance(Hex a, Hex b) const`: the number of neighbour steps of a shortest route, taking the wrap-around into account. Without wrapping, the
      distance is computed in cube coordinates: `x = col - (row - (row & 1)) / 2`, `z = row`, `y = -x - z`, and the distance is
      `max(|dx|, |dy|, |dz|)`. On the torus the distance is the smallest of these over the nine copies of `b` shifted by `(i*w, j*h)` for
      `i, j` in `{-1, 0, 1}` (both `a` and `b` are wrapped first).
    * `std::vector<Hex> within(Hex center, int radius) const`: every distinct cell of the map whose distance from `center` is `<= radius`, sorted by row, then
      by column. A negative radius gives an empty list.
    * `std::vector<Hex> ring(Hex center, int radius) const`: the cells at distance exactly `radius`, sorted the same way. `ring(c, 0)` is `{c}`; a
      negative radius gives an empty list.
    * `int region_size(Hex start, const std::vector<bool> &blocked) const`: the number of cells reachable from `start` by neighbour steps without entering a blocked
      cell, `start` included. `blocked` is indexed by `index`; its size must be `w * h` (`std::invalid_argument` otherwise). A blocked `start` gives 0.
''')

F2 = dd(r'''
    #ifndef HEXWRAP_HPP
    #define HEXWRAP_HPP

    #include <array>
    #include <stdexcept>
    #include <vector>

    namespace hexwrap {

    struct Hex {
        int col;
        int row;
    };

    inline bool operator==(Hex a, Hex b) { return a.col == b.col && a.row == b.row; }

    enum Dir { E = 0, NE = 1, NW = 2, W = 3, SW = 4, SE = 5 };

    class Map {
    public:
        Map(int w, int h);
        int width() const { return w_; }
        int height() const { return h_; }
        Hex wrap(Hex h) const;
        int index(Hex h) const;
        Hex from_index(int i) const;
        std::array<Hex, 6> neighbors(Hex h) const;
        Hex step(Hex h, Dir d, int n) const;
        int distance(Hex a, Hex b) const;
        std::vector<Hex> within(Hex center, int radius) const;
        std::vector<Hex> ring(Hex center, int radius) const;
        int region_size(Hex start, const std::vector<bool> &blocked) const;

    private:
        int w_, h_;
    };

    }  // namespace hexwrap

    #endif
''')

F3 = dd(r'''
    #include "hexwrap.hpp"

    #include <cstdlib>

    namespace hexwrap {

    static int mod(int a, int m) {
        int r = a % m;
        return r < 0 ? r + m : r;
    }

    Map::Map(int w, int h) : w_(w), h_(h) {
        if (w < 1 || h < 2 || h % 2 != 0) throw std::invalid_argument("bad map size");
    }

    Hex Map::wrap(Hex h) const { return Hex{mod(h.col, w_), mod(h.row, h_)}; }

    int Map::index(Hex h) const {
        Hex c = wrap(h);
        return c.row * w_ + c.col;
    }

    Hex Map::from_index(int i) const { return Hex{i % w_, i / w_}; }

    std::array<Hex, 6> Map::neighbors(Hex h) const {
        Hex c = wrap(h);
        int odd = c.row & 1;
        std::array<Hex, 6> out = {
            Hex{c.col + 1, c.row},
            Hex{c.col + odd, c.row - 1},
            Hex{c.col - 1 + odd, c.row - 1},
            Hex{c.col - 1, c.row},
            Hex{c.col - 1 + odd, c.row + 1},
            Hex{c.col + odd, c.row + 1},
        };
        for (Hex &n : out) n = wrap(n);
        return out;
    }

    Hex Map::step(Hex h, Dir d, int n) const {
        if (n > 10000 || n < -10000) throw std::invalid_argument("too many steps");
        int dir = static_cast<int>(d);
        if (n < 0) {
            dir = (dir + 3) % 6;
            n = -n;
        }
        Hex cur = wrap(h);
        for (int i = 0; i < n; i++) cur = neighbors(cur)[static_cast<size_t>(dir)];
        return cur;
    }

    static int cube_distance(Hex a, Hex b) {
        int ax = a.col - (a.row - (a.row & 1)) / 2, az = a.row, ay = -ax - az;
        int bx = b.col - (b.row - (b.row & 1)) / 2, bz = b.row, by = -bx - bz;
        int dx = std::abs(ax - bx), dy = std::abs(ay - by), dz = std::abs(az - bz);
        return dx > dy ? (dx > dz ? dx : dz) : (dy > dz ? dy : dz);
    }

    int Map::distance(Hex a, Hex b) const {
        Hex wa = wrap(a), wb = wrap(b);
        int best = -1;
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                int d = cube_distance(wa, Hex{wb.col + i * w_, wb.row + j * h_});
                if (best < 0 || d < best) best = d;
            }
        }
        return best;
    }

    std::vector<Hex> Map::within(Hex center, int radius) const {
        std::vector<Hex> out;
        if (radius < 0) return out;
        for (int r = 0; r < h_; r++) {
            for (int c = 0; c < w_; c++) {
                if (distance(center, Hex{c, r}) <= radius) out.push_back(Hex{c, r});
            }
        }
        return out;
    }

    std::vector<Hex> Map::ring(Hex center, int radius) const {
        std::vector<Hex> out;
        if (radius < 0) return out;
        for (int r = 0; r < h_; r++) {
            for (int c = 0; c < w_; c++) {
                if (distance(center, Hex{c, r}) == radius) out.push_back(Hex{c, r});
            }
        }
        return out;
    }

    int Map::region_size(Hex start, const std::vector<bool> &blocked) const {
        if (blocked.size() != static_cast<size_t>(w_) * static_cast<size_t>(h_)) throw std::invalid_argument("blocked has the wrong size");
        int s = index(start);
        if (blocked[static_cast<size_t>(s)]) return 0;
        std::vector<bool> seen(blocked.size(), false);
        std::vector<int> queue;
        queue.push_back(s);
        seen[static_cast<size_t>(s)] = true;
        for (size_t head = 0; head < queue.size(); head++) {
            for (Hex n : neighbors(from_index(queue[head]))) {
                int k = index(n);
                if (!blocked[static_cast<size_t>(k)] && !seen[static_cast<size_t>(k)]) {
                    seen[static_cast<size_t>(k)] = true;
                    queue.push_back(k);
                }
            }
        }
        return static_cast<int>(queue.size());
    }

    }  // namespace hexwrap
''')

V4 = dd(r'''
    #include "harness.hpp"
    #include "hexwrap.hpp"

    using namespace hexwrap;

    int main() {
        h_init();
        Map m(6, 4);
        auto n = m.neighbors(Hex{2, 1});
        CHECK_EQ(n[0].col, 3);
        CHECK_EQ(n[1].col, 3);
        CHECK_EQ(n[1].row, 0);
        CHECK_EQ(m.distance(Hex{0, 0}, Hex{3, 0}), 3);
        CHECK_EQ(m.distance(Hex{0, 0}, Hex{5, 0}), 1);
        return h_report();
    }
''')

